@push('scripts')<script>$(function(){$('.js-post').on('click',function(){const b=$(this);Swal.fire({icon:'warning',text:'ยืนยัน Post การจ่ายและบันทึก GL?',showCancelButton:true,confirmButtonText:'Post การจ่าย',cancelButtonText:'ย้อนกลับ'}).then(r=>{if(!r.isConfirmed)return;b.prop('disabled',true);$.ajax({url:b.data('url'),method:'POST',headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content'),Accept:'application/json'}}).done(x=>location.href=x.redirect).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'ไม่สามารถ Post การจ่ายได้'})).always(()=>b.prop('disabled',false));});});});</script>@endpush
